style.css:
@-moz-document domain("chat.openai.com") {
/* Main background */
  body, #__next, .overflow-hidden, .flex, .bg-token-main-surface-primary {
    background-color: #eaf8ff !important; /* very light baby blue */
    color: #6aa9ff !important; /* pastel light blue text */
  }

  /* Sidebar */
  nav, .bg-token-sidebar-surface-primary, .sticky, .flex-col {
    background-color: #f8f8f2 !important; /* off-white */
    color: #6aa9ff !important;
  }

  /* Chat messages */
  .markdown, .prose, .whitespace-pre-wrap, .text-token-text-primary {
    background-color: #fdfdf9 !important; /* off-white with blue tint */
    color: #6aa9ff !important;
  }

  /* Input box */
  textarea, .sticky.bottom-0, .bg-token-main-surface-tertiary {
    background-color: #eaf8ff !important;
    color: #6aa9ff !important;
    border: 1px solid #cce7ff !important;
  }

  /* Buttons */
  button, .btn, .rounded-md {
    background-color: #f8f8f2 !important;
    color: #6aa9ff !important;
    border: 1px solid #cce7ff !important;
  }

  button:hover, .btn:hover {
    background-color: #eaf8ff !important;
    color: #6aa9ff !important;
  }
}
